xql_query:
// ============================================================
// Rule: CTX_Endpoint EDR Protection Manually Paused
// Vendor: Cortex
// Objective:
// Detect activity associated with CTX_Endpoint EDR Protection Manually Paused.
// Severity: SEV_040_HIGH
// Category: EVASION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0005 - Defense Evasion
// Technique: T1562.001 - Impair Defenses: Disable or Modify Tools
// Technique: T1562 - Impair Defenses

// Configuração inicial: comparações não diferenciam maiúsculas/minúsculas
// Objetivo: capturar variações de caixa no comando (ex.: "Protect Disable", "PROTECT DISABLE")
config case_sensitive = false

// Fonte de dados: telemetria do agente (processos/comandos executados nos endpoints)
| dataset = xdr_data

// Filtro: identifica execução de comando relacionado à desativação de proteção
// Observação: 'os_actor_process_command_line' representa a linha de comando observada pelo SO/agente
| filter os_actor_process_command_line contains "protect disable"

// Agregação: consolida ocorrências por endpoint e usuário executor
| comp
    count() as Total_Execucoes
  by agent_hostname, actor_effective_username

// Saída final (útil para alerta/dash)
| fields agent_hostname, actor_effective_username, Total_Execucoes
